#include "stdafx.h"#include "FBDsConverter.h"#include "OpenXmlExport.h"#include "Trim.h"#include <io.h>using namespace tinyxml2;using namespace std;eTypeText TrimName( string &name );KOpenXmlExport::KOpenXmlExport(){}void KOpenXmlExport::Export2OpenXml( LPCSTR pszDirOut ){  if( !pszDirOut )    return;  if( _access(pszDirOut, 0) )    return;  char szFileName[_MAX_FNAME] = {};  sprintf_s( szFileName, "%02d-%02d-%02d", atoi(m_WorkSheet.index.c_str()), atoi(m_curPage.c_str()), atoi(m_ofPage.c_str()) );  char szPath[_MAX_PATH];  _makepath_s( szPath, NULL, pszDirOut, szFileName, "xml" );  tinyxml2::XMLDocument doc;  XMLDeclaration* pDecl = doc.NewDeclaration( "xml version=\"1.0\" encoding=\"Windows-1251\"" );  doc.InsertFirstChild( pDecl );  tinyxml2::XMLElement* pRoot = doc.NewElement("HcdLogix");  Export( pRoot );  doc.InsertEndChild( pRoot );  tinyxml2::XMLError err = doc.SaveFile( szPath );  KKK();}void KOpenXmlExport::Export( tinyxml2::XMLElement* pRoot ){  pRoot->SetAttribute( "Title", m_WorkSheet.title.c_str() );  pRoot->SetAttribute( "Description", m_WorkSheet.description.c_str() );  pRoot->SetAttribute( "WorksheetIndex", m_WorkSheet.index.c_str() );  tinyxml2::XMLElement* pPage = pRoot->GetDocument()->NewElement( "Page" );  pRoot->InsertEndChild( pPage );  ExportCurPage( pPage );}void KOpenXmlExport::ExportCurPage( tinyxml2::XMLElement* pRoot ){  pRoot->SetAttribute( "number", m_curPage.c_str() );  pRoot->SetAttribute( "ofPages", m_ofPage.c_str() );  tinyxml2::XMLElement* p = pRoot->GetDocument()->NewElement( "Elements" );  pRoot->InsertEndChild( p );  ExportOrderedElements( p );  p = pRoot->GetDocument()->NewElement( "Connections" );  pRoot->InsertEndChild( p );  ExportConnections( p );}void KOpenXmlExport::ExportOrderedElements( tinyxml2::XMLElement* pRoot ){  int J = 0;  for( tFullBlocksCont_::iterator it=m_Blocks.begin(), end(m_Blocks.end()); it!=end; ++it, ++J )  {    tBlocksWithPinsPtr& bl = (*it);    tGraphObjPointsPtr_ &gObj = bl->graphBlock;    string elemType = bl->szBlockType;    string type;    switch( gObj->GetRawDrawType() )    {    case ertBitBlt:      elemType = "Block";      type = bl->szBlockType;      break;    }    tinyxml2::XMLElement* pBlock = pRoot->GetDocument()->NewElement( elemType.c_str() );    pRoot->InsertEndChild( pBlock );    if( !type.empty() )      pBlock->SetAttribute( "Type", type.c_str() );    ExportBlockConfig( pBlock, bl, type.c_str() );  }}void KOpenXmlExport::ExportBlockParams( tinyxml2::XMLElement* pElement, tParamsCont_ &params ){  if( params.empty() )    return;  tinyxml2::XMLElement* pParams = pElement->GetDocument()->NewElement( "Parameters" );  pElement->InsertEndChild( pParams );  for( tParamsCont_::iterator it=params.begin(), end(params.end()); it!=end; ++it )  {    SNamedParam &para = *it;    tinyxml2::XMLElement* pParam = pParams->GetDocument()->NewElement( "Parameter" );    pParams->InsertEndChild( pParam );    tinyxml2::XMLElement* pName = pParams->GetDocument()->NewElement( "Name" );    pParam->InsertEndChild( pName );    tinyxml2::XMLElement* pValue = pParams->GetDocument()->NewElement( "Value" );    pParam->InsertEndChild( pValue );    pName->SetText( para.name.c_str() );    pValue->SetText( para.value.c_str() );  }}void KOpenXmlExport::ExportBlockConfig( tinyxml2::XMLElement* pRoot, tBlocksWithPinsPtr& bl, LPCSTR pszType ){  tGraphObjPointsPtr_ &gObj = bl->graphBlock;  string srcName = gObj->GetName();  TrimName( srcName );  pRoot->SetAttribute( "ID", gObj->GetID() );  pRoot->SetAttribute( "ExecOrder", bl->ExecOrder );  pRoot->SetAttribute( "Name", srcName.c_str() );  if( !bl->szDataType.empty() )  {    pRoot->SetAttribute( "DataType", bl->szDataType.c_str() );    LPCSTR pszNodeName = pRoot->Name();    if( !strcmp( pszNodeName, "VariableIn") )    {      string initVal = m_paramReader.GetRawInitialValue( srcName.c_str(), bl->szDataType=="Analog" ? 0 : 1 );      if( !initVal.empty() )        pRoot->SetAttribute( "InitialValue", initVal.c_str() );      int N = m_paramReader.GetVariableNumber( srcName.c_str() );      if( N > 0 )        pRoot->SetAttribute( "Number", N );    }    else if( !strcmp( pszNodeName, "SignalSource") || !strcmp( pszNodeName, "SignalDest") )    {      int N = m_paramReader.GetSignalNumber( srcName.c_str() );      if( N > 0 )        pRoot->SetAttribute( "Number", N );    }  }  string t = m_paramReader.GetElementDescription( srcName.c_str() );  if( !t.empty() )    pRoot->SetAttribute( "Description", t.c_str() );  t = m_paramReader.GetElementUnits( srcName.c_str() );  if( !t.empty() )    pRoot->SetAttribute( "Units", t.c_str() );  switch( gObj->GetRawDrawType() )  {  case ertBitBlt:    {      tVectoredString_ sets;      tParamsCont_ params;      m_paramReader.GetElementSettings( srcName.c_str(), sets, params );      if( pszType )      {        if( !strcmp( pszType, "WVAR") )        {          string tn = gObj->GetTagName();          ASSD( !tn.empty() );          if( !tn.empty() )          {            SNamedParam nv = { "Variable Name", tn.c_str() };            params.push_back( nv );          }        }        if( !strcmp( pszType, "PID") || !strcmp( pszType, "TCPS") || !strcmp( pszType, "TPSC") )        {          string tn = gObj->GetTagName();          ASSD( !tn.empty() );          if( !tn.empty() )            pRoot->SetAttribute( "HmiTagName", tn.c_str() );        }      }      ExportBlockParams( pRoot, params );    }    break;  }}void KOpenXmlExport::ExportConnections( tinyxml2::XMLElement* pRoot ){  int J = 0;  for( tFullBlocksCont_::iterator itB=m_Blocks.begin(), endB(m_Blocks.end()); itB!=endB; ++itB, ++J )  {    tBlocksWithPinsPtr& bl = (*itB);    if( bl->outConnections.empty() )      continue;    tGraphObjPointsPtr_ &gObj = bl->graphBlock;    string srcName = gObj->GetName();    TrimName( srcName );        tinyxml2::XMLElement* pBOCs = pRoot->GetDocument()->NewElement( "BlockOutConnections" );    pRoot->InsertEndChild( pBOCs );    pBOCs->SetAttribute( "BlockName", srcName.c_str() );    pBOCs->SetAttribute( "ID", gObj->GetID() );    for( tAllConnectionsCont_::iterator itC=bl->outConnections.begin(), endC(bl->outConnections.end()); itC!=endC; ++itC )    {      tElementOutsConnectionPtr &con = (*itC);      tPinConnectionPtr pinOutInfo = bl->GetOutPinInfo( con->pinOut->GetID() );      for( tConInfoCont_::iterator it=con->dests.begin(), end(con->dests.end()); it!=end; ++it )      {        tPinConnectionPtr &pincon = *it;        tinyxml2::XMLElement* pCon = pRoot->GetDocument()->NewElement( "Connection" );        pBOCs->InsertEndChild( pCon );        switch( con->dataType )        {        default:          ASSD(0);          break;        case esotAnalog:          pCon->SetAttribute( "dataType", "Analog" );          break;        case esotDigital:          pCon->SetAttribute( "dataType", "Digital" );          break;        }        tinyxml2::XMLElement* pSrc = pRoot->GetDocument()->NewElement( "Source" );        pCon->InsertEndChild( pSrc );        pSrc->SetAttribute( "Pin", pinOutInfo->szIndexName.c_str() );        tinyxml2::XMLElement* pSinc = pRoot->GetDocument()->NewElement( "Sink" );        pCon->InsertEndChild( pSinc );        string sincName = pincon->ptrObjG->GetName();        TrimName( sincName );        pSinc->SetAttribute( "BlockName", sincName.c_str() );        pSinc->SetAttribute( "ID", pincon->ptrObjG->GetID() );        pSinc->SetAttribute( "Pin", pincon->szIndexName.c_str() );      }      KKK();    }  }}